<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Expense Tracker</title>
<style>
  :root {
    --bg: #f4f5f7;
    --card: #ffffff;
    --border: #d9dce1;
    --accent: #2f6fed;
    --danger: #d9463e;
    --text: #23272e;
    --muted: #6b7280;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.4;
  }
  .wrap {
    max-width: 820px;
    margin: 0 auto;
    padding: 24px 16px 60px;
  }
  h1 { font-size: 1.5rem; margin: 0 0 20px; }
  .card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px;
    margin-bottom: 20px;
  }
  .card h2 {
    font-size: 1rem;
    margin: 0 0 14px;
    text-transform: uppercase;
    letter-spacing: .04em;
    color: var(--muted);
  }
  form .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
  }
  label {
    display: block;
    font-size: .8rem;
    color: var(--muted);
    margin-bottom: 4px;
  }
  input, select, button {
    font: inherit;
    padding: 8px 10px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text);
    width: 100%;
  }
  button {
    cursor: pointer;
    width: auto;
  }
  .btn-primary {
    background: var(--accent);
    color: #fff;
    border-color: var(--accent);
    font-weight: 600;
    margin-top: 14px;
    padding: 9px 20px;
  }
  .btn-primary:hover { filter: brightness(1.05); }
  #form-error {
    color: var(--danger);
    font-size: .85rem;
    min-height: 1.1em;
    margin-top: 10px;
  }
  #form-error:empty { margin-top: 0; }
  .filters .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
  }
  .summary-row {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: center;
    margin-bottom: 14px;
  }
  .total-box {
    font-size: 1.1rem;
    font-weight: 700;
  }
  .total-box #total { color: var(--accent); }
  .cats {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-left: auto;
  }
  .cat-total {
    background: #eef2fb;
    border: 1px solid #dce4f7;
    border-radius: 20px;
    padding: 4px 12px;
    font-size: .82rem;
  }
  .cat-total .lbl { color: var(--muted); text-transform: capitalize; }
  table {
    width: 100%;
    border-collapse: collapse;
  }
  th, td {
    text-align: left;
    padding: 9px 8px;
    border-bottom: 1px solid var(--border);
    font-size: .92rem;
  }
  th {
    font-size: .72rem;
    text-transform: uppercase;
    letter-spacing: .04em;
    color: var(--muted);
  }
  td.amt { font-variant-numeric: tabular-nums; font-weight: 600; }
  .cat-badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 20px;
    background: #eef2fb;
    font-size: .8rem;
    text-transform: capitalize;
  }
  .exp-del {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--danger);
    border-radius: 6px;
    padding: 4px 10px;
    font-size: .82rem;
  }
  .exp-del:hover { background: var(--danger); color: #fff; border-color: var(--danger); }
  .empty {
    color: var(--muted);
    text-align: center;
    padding: 24px;
    font-size: .9rem;
  }
  .note-cell { color: var(--muted); font-size: .85rem; }
</style>
</head>
<body>
<div class="wrap">
  <h1>💸 Personal Expense Tracker</h1>

  <div class="card">
    <h2>Add Expense</h2>
    <form id="expense-form" novalidate>
      <div class="grid">
        <div>
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" placeholder="0.00" inputmode="decimal">
        </div>
        <div>
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </div>
        <div>
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div>
          <label for="note">Note (optional)</label>
          <input type="text" id="note" placeholder="e.g. weekly shop">
        </div>
      </div>
      <button type="submit" id="add-expense" class="btn-primary">Add Expense</button>
      <div id="form-error" role="alert"></div>
    </form>
  </div>

  <div class="card filters">
    <h2>Filters</h2>
    <div class="grid">
      <div>
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">All</option>
          <option value="groceries">Groceries</option>
          <option value="transport">Transport</option>
          <option value="bills">Bills</option>
          <option value="fun">Fun</option>
        </select>
      </div>
      <div>
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div>
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
    </div>
  </div>

  <div class="card">
    <h2>Summary</h2>
    <div class="summary-row">
      <div class="total-box">Visible Total: <span id="total">0.00</span></div>
      <div class="cats" id="cat-summary"></div>
    </div>
    <table>
      <thead>
        <tr>
          <th>Amount</th>
          <th>Category</th>
          <th>Date</th>
          <th>Note</th>
          <th></th>
        </tr>
      </thead>
      <tbody id="expense-list"></tbody>
    </table>
    <div class="empty" id="empty-msg" style="display:none;">No expenses to show.</div>
  </div>
</div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "expense-tracker-v1";
  var CATEGORIES = ["groceries", "transport", "bills", "fun"];

  var form = document.getElementById("expense-form");
  var amountEl = document.getElementById("amount");
  var categoryEl = document.getElementById("category");
  var dateEl = document.getElementById("date");
  var noteEl = document.getElementById("note");
  var errorEl = document.getElementById("form-error");

  var filterCatEl = document.getElementById("filter-category");
  var filterFromEl = document.getElementById("filter-from");
  var filterToEl = document.getElementById("filter-to");

  var listEl = document.getElementById("expense-list");
  var totalEl = document.getElementById("total");
  var catSummaryEl = document.getElementById("cat-summary");
  var emptyMsgEl = document.getElementById("empty-msg");

  var expenses = load();

  // Default the date field to today for convenience.
  dateEl.value = todayISO();

  // Build the per-category summary elements once.
  var catTotalEls = {};
  CATEGORIES.forEach(function (cat) {
    var span = document.createElement("span");
    span.className = "cat-total";
    span.setAttribute("data-cat", cat);
    span.innerHTML = '<span class="lbl">' + cat + ':</span> <span class="val">0.00</span>';
    catSummaryEl.appendChild(span);
    catTotalEls[cat] = span.querySelector(".val");
  });

  function todayISO() {
    var d = new Date();
    var m = String(d.getMonth() + 1).padStart(2, "0");
    var day = String(d.getDate()).padStart(2, "0");
    return d.getFullYear() + "-" + m + "-" + day;
  }

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (e) {
        return e && typeof e.amount === "number" && e.category && e.date;
      });
    } catch (err) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) {
      /* ignore quota / unavailable storage */
    }
  }

  function fmt(n) {
    return n.toFixed(2);
  }

  function makeId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    errorEl.textContent = "";

    var raw = amountEl.value.trim();
    var amount = Number(raw);

    if (raw === "" || !isFinite(amount) || amount <= 0) {
      errorEl.textContent = "Please enter an amount greater than zero.";
      return;
    }
    if (!dateEl.value) {
      errorEl.textContent = "Please choose a date.";
      return;
    }

    expenses.push({
      id: makeId(),
      amount: amount,
      category: categoryEl.value,
      date: dateEl.value,
      note: noteEl.value.trim()
    });

    save();
    errorEl.textContent = "";
    amountEl.value = "";
    noteEl.value = "";
    render();
    amountEl.focus();
  });

  listEl.addEventListener("click", function (e) {
    var btn = e.target.closest(".exp-del");
    if (!btn) return;
    var id = btn.getAttribute("data-id");
    expenses = expenses.filter(function (x) { return x.id !== id; });
    save();
    render();
  });

  [filterCatEl, filterFromEl, filterToEl].forEach(function (el) {
    el.addEventListener("change", render);
    el.addEventListener("input", render);
  });

  function passesFilter(exp) {
    if (filterCatEl.value !== "all" && exp.category !== filterCatEl.value) {
      return false;
    }
    if (filterFromEl.value && exp.date < filterFromEl.value) {
      return false;
    }
    if (filterToEl.value && exp.date > filterToEl.value) {
      return false;
    }
    return true;
  }

  function render() {
    // Newest first: sort by date desc, then by insertion order (id carries time).
    var sorted = expenses.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return a.id < b.id ? 1 : -1;
    });

    var visible = sorted.filter(passesFilter);

    listEl.innerHTML = "";
    var total = 0;
    var catTotals = { groceries: 0, transport: 0, bills: 0, fun: 0 };

    visible.forEach(function (exp) {
      total += exp.amount;
      if (catTotals.hasOwnProperty(exp.category)) {
        catTotals[exp.category] += exp.amount;
      }

      var tr = document.createElement("tr");
      tr.className = "expense";
      tr.setAttribute("data-id", exp.id);

      var tdAmt = document.createElement("td");
      tdAmt.className = "amt";
      tdAmt.textContent = fmt(exp.amount);

      var tdCat = document.createElement("td");
      var badge = document.createElement("span");
      badge.className = "cat-badge";
      badge.textContent = exp.category;
      tdCat.appendChild(badge);

      var tdDate = document.createElement("td");
      tdDate.textContent = exp.date;

      var tdNote = document.createElement("td");
      tdNote.className = "note-cell";
      tdNote.textContent = exp.note || "";

      var tdDel = document.createElement("td");
      var del = document.createElement("button");
      del.className = "exp-del";
      del.type = "button";
      del.setAttribute("data-id", exp.id);
      del.textContent = "Delete";
      tdDel.appendChild(del);

      tr.appendChild(tdAmt);
      tr.appendChild(tdCat);
      tr.appendChild(tdDate);
      tr.appendChild(tdNote);
      tr.appendChild(tdDel);
      listEl.appendChild(tr);
    });

    totalEl.textContent = fmt(total);
    CATEGORIES.forEach(function (cat) {
      catTotalEls[cat].textContent = fmt(catTotals[cat]);
    });

    emptyMsgEl.style.display = visible.length ? "none" : "block";
  }

  render();
})();
</script>
</body>
</html>
